const hasWord = (text: string, word: string) => new RegExp(`(^|[^a-z0-9])${escapeRe(word)}(s|es)?([^a-z0-9]|$)`).test(text);

/** Same keyword scoring the forge router uses (lib/cyrus/engine routePrompt), over the build's own words. */
export function scoreCategory(text: string): CategoryKey | null {
  const p = text.toLowerCase();
  let best: CategoryKey | null = null;
  let bestScore = 0;
  for (const c of CATEGORIES) {
    let score = 0;
    for (const k of c.keywords) if (hasWord(p, k)) score += k.length;
    if (score > bestScore) { bestScore = score; best = c.key; }
  }
  return best;
}

