/**
 * Project Zomboid needs BOTH the numeric Workshop id (`WorkshopItems=`) AND
 * the mod's own internal string id from its `mod.info` file (`Mods=`) — two
 * different values, confirmed against PZwiki. The Workshop API never exposes
 * the second one; the only way to learn it is to look inside the mod's own
 * files. We do that with a single, throwaway `steamcmd workshop_download_item`
 * run INSIDE the customer's own container (Valve's own tool, on their own
 * VM — not a Nxeon download/mirror), read `mod.info`, then delete what we
 * fetched immediately — the dedicated server re-fetches its own real copy on
 * boot via `WorkshopItems=`, so nothing is kept or served from here. The
 * result is cached onto the `GameMod` row so this only ever runs once per
 * mod, for any server.
 */
async function resolvePzModStringId(conn: Client, sourceId: string): Promise<string | null> {
  const tmp = `/tmp/nxw-${sourceId.replace(/[^0-9]/g, "")}`;
  const cmd =
    `docker exec projectzomboid steamcmd +login anonymous +force_install_dir '${shq(tmp)}' +workshop_download_item ${PZ_APPID} ${shq(sourceId)} +quit >/dev/null 2>&1; ` +
    `docker exec projectzomboid sh -c "find '${shq(tmp)}' -iname mod.info 2>/dev/null | head -5 | xargs -r cat" 2>/dev/null; ` +
    `docker exec projectzomboid rm -rf '${shq(tmp)}' >/dev/null 2>&1`;
  const { stdout } = await execRemote(conn, cmd);
  const ids = [...stdout.matchAll(/^\s*id\s*=\s*(.+?)\s*$/gim)].map((m) => m[1].trim()).filter(Boolean);
  return ids.length ? ids.join(";") : null;
}

const PZ_APPID = WORKSHOP_APPID.projectzomboid;

async function applyProjectZomboidWorkshop(
  server: SshServer,
  mods: { sourceId: string; modStringId: string | null; gameModId: string }[]
): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    const resolved: string[] = [];
    for (const m of mods) {
      if (m.modStringId) {
        resolved.push(m.modStringId);
        continue;
      }
      const found = await resolvePzModStringId(conn, m.sourceId);
      if (!found) {
        return {
          ok: false,
          error: `Could not read this mod's internal Mod ID from Steam Workshop item ${m.sourceId} — it may be private, removed, or not a real PZ mod.`,
        };
      }
      await db.gameMod.update({ where: { id: m.gameModId }, data: { modStringId: found }, select: { id: true } }).catch(() => {});
      resolved.push(found);
    }

    const dir = "/opt/projectzomboid/config/Server";
    await execRemote(conn, `mkdir -p '${shq(dir)}'`);
    // SERVER_NAME=servertest, fixed by this platform's projectzomboid setupScript (prisma/seed-wave1/7-games.ts).
    const path = `${dir}/servertest.ini`;
    const existing = (await sftpRead(sftp, path)) ?? "";
    const updated = updateIniKeyValue(existing, {
      WorkshopItems: mods.map((m) => m.sourceId).join(";"),
      Mods: resolved.join(";"),
    });
    await sftpWrite(sftp, path, updated);
    return { ok: true };
  });
}

function stripMarkedBlock(content: string, start: string, end: string): string {
  const s = content.indexOf(start);
  if (s < 0) return content;
  const e = content.indexOf(end, s);
  if (e < 0) return content;
  return content.slice(0, s) + content.slice(e + end.length);
}

