  neon: { hit: 'Fx.toast(Fx.text("hit", "%s  -%d", Fx.palName(TARGET), info.NativeDamageValue))', pulse: 'Fx.toast(Fx.text("pulse", "%s ▸ surge", Fx.palName(TARGET)))', needs: [] },
};

function fxDefs(keys: EffectKey[], n: N, palId: string): Def[] {
  const has = (...k: EffectKey[]) => k.some((x) => keys.includes(x));
  const out: Def[] = [];
  if (has("frost", "fire", "storm", "poison")) out.push(["duration", String(n.duration), "status ailment length (seconds)"]);
  if (has("heal", "void", "lunar")) out.push(["power", String(n.power), "base heal / drain per proc (HP)"]);
  if (has("blink")) out.push(["blinkDistance", String(n.radius * 100), "blink distance (cm)"]);
  if (has("summon")) out.push(["summonChance", String(n.chance), "chance to call an echo per proc"], ["summonId", `"${palId}"`, "DT_PalMonsterParameter row to summon"]);
  if (has("flight")) out.push(["jumpMultiplier", (1.6 + n.speed * 2).toFixed(2), "JumpZVelocity multiplier while launched"]);
