/**
 * Project Zomboid · Build 42 (42.15+, checked on 42.21) · Lua + script files.
 *
 * Layout (Mod structure, PZwiki 42.21): the project root IS the mod folder that goes into
 * `Zomboid/mods/` (or `Workshop/<Item>/Contents/mods/`):
 *   42/mod.info                                   id, name, modversion, versionMin
 *   42/media/sandbox-options.txt                  every tunable number (SandboxVars.<ModId>.*)
 *   42/media/lua/shared/<ModId>/Config.lua        defaults + pure helpers (unit-tested)
 *   42/media/lua/shared/<ModId>/Effects.lua       game-state changes; only ever run server-side (or SP)
 *   42/media/lua/shared/<ModId>/Actions.lua       timed actions (shared, getDuration + complete, 42.13 MP rules)
 *   42/media/lua/client/<ModId>/Client.lua        triggers, UI, requests to the server
 *   42/media/lua/server/<ModId>/Server.lua        command handler, loot, timers
 *   42/media/scripts/<mod>/*.txt                  items, recipes, vehicles, sounds (own module)
 *   common/media/lua/shared/Translate/EN/*.json   translations (JSON since 42.15)
 *
 * Multiplayer (42.13 migration guide + Networking, 42.13.1): the server owns items, health and stats.
 * So clients only detect triggers and `sendClientCommand`; the server checks distance, cooldowns and what
 * the player holds, then applies the effect. In singleplayer the command loops straight back.
 *
 * Every Java/Lua API used below was checked against the 42.21 JavaDocs / 42.20 LuaDocs; the list and the
 * removed calls it replaced are in /root/agent-notes/cyrus-v6/game-zomboid/API-CHECK.md.
 *
 * Katara (lite) output is capped at three files, so it folds everything into one shared file that
 * splits itself with isServer()/isClient() guards.
 */
import type { CategoryKey, ModFile } from "@/lib/cyrus/types";
import { PZ_TARGET } from "@/lib/cyrus/games/zomboid";
import { ARCH, code, deriveFeatures, effectsFor, file, hashStr, identity, MODEL_NAME, numbers, type Built, type EffectKey, type TemplateInput } from "../kit";

/* ═════════════════════════ effects ═════════════════════════ */

/**
 * foe(target, source, power) hits a zombie or player · self(who, power) acts on the user · world(square, source, power)
 * touches the map. `local` effects only touch the local player's UI or queue vanilla timed actions, so they run on the
 * client; everything else changes game state and runs on the server.
 */
type Kind = "foe" | "self" | "world";
type FxDef = { kind: Kind; local?: true; outfit: string; drop: string; part: string; hud: [string, string]; needs?: ("nudge" | "hurt" | "burn")[]; lua: string };

/** HUD readouts, client side. `stat()` is defined in the HUD file and reads the B42 CharacterStat API. */
const FX: Record<EffectKey, FxDef> = {
  frost: { kind: "foe", outfit: "Hunter", drop: "Base.Matches", part: "Base.Aluminum", hud: ["Cold", 'stat(player, "TEMPERATURE")'], needs: ["nudge"], lua: `if instanceof(target, "IsoZombie") then
    target:setWalkType("slow3")
else
    nudge(target, "FATIGUE", 0.01 * power)
    nudge(target, "ENDURANCE", -0.01 * power)
end` },
  fire: { kind: "world", outfit: "Fireman", drop: "Base.Lighter", part: "Base.PropaneTank", hud: ["Outside", 'string.format("%.0f C", getClimateManager():getTemperature())'], needs: ["burn"], lua: `if canBurn(square) then
    IsoFireManager.StartFire(square:getCell(), square, true, math.floor(60 + power * 4))
end` },
  storm: { kind: "world", outfit: "Police", drop: "Base.Battery", part: "Base.Battery", hud: ["Rain", 'string.format("%d%%", getClimateManager():getPrecipitationIntensity() * 100)'], needs: ["hurt"], lua: `getClimateManager():getThunderStorm():triggerThunderEvent(square:getX(), square:getY(), true, true, true)
local struck = square:getMovingObjects()
for i = struck:size() - 1, 0, -1 do
    local zombie = struck:get(i)
    if instanceof(zombie, "IsoZombie") and not zombie:isDead() then hurt(zombie, power * 0.1, source) end
end
getWorldSoundManager():addSound(source, square:getX(), square:getY(), square:getZ(), math.floor(power * 4), 100)` },
  blink: { kind: "self", outfit: "Survivalist", drop: "Base.ElectronicsScrap", part: "Base.ElectronicsScrap", hud: ["Endurance", 'stat(player, "ENDURANCE")'], needs: ["nudge"], lua: `if isServer() and instanceof(who, "IsoPlayer") then
    -- a dedicated server owns player positions; a teleport there trips the anti-cheat, so it becomes a burst of stamina
    return nudge(who, "ENDURANCE", 0.15)
end
local dir, reach = who:getForwardDirection(), math.min(8, 2 + power * 0.4)
local x, y, z = who:getX() + dir:getX() * reach, who:getY() + dir:getY() * reach, math.floor(who:getZ())
local square = getCell():getGridSquare(math.floor(x), math.floor(y), z)
if square and square:isFree(false) then who:teleportTo(x, y, z) end` },
  heal: { kind: "self", outfit: "Doctor", drop: "Base.Bandage", part: "Base.Bandage", hud: ["Health", 'string.format("%d%%", player:getBodyDamage():getOverallBodyHealth())'], lua: `if instanceof(who, "IsoPlayer") then
    who:getBodyDamage():AddGeneralHealth(power * 0.5)
else
    who:setHealth(who:getHealth() + power * 0.01)
end` },
  poison: { kind: "foe", outfit: "HazardSuit", drop: "Base.Hat_GasMask", part: "Base.Bleach", hud: ["Poison", 'stat(player, "POISON")'], needs: ["nudge", "hurt"], lua: `if instanceof(target, "IsoPlayer") then
    nudge(target, "POISON", 0.02 * power)
else
    hurt(target, power * 0.02, source)
end` },
  summon: { kind: "world", outfit: "Inmate", drop: "Base.Garbagebag", part: "Base.RippedSheets", hud: ["Kills", "tostring(player:getZombieKills())"], lua: `local pack = addZombiesInOutfit(square:getX(), square:getY(), square:getZ(), math.max(1, math.floor(power / 4)), nil, 50)
for i = 0, pack:size() - 1 do
    pack:get(i):pathToSound(math.floor(source:getX()), math.floor(source:getY()), math.floor(source:getZ()))
end` },
  flight: { kind: "self", outfit: "Biker", drop: "Base.Rope", part: "Base.Rope", hud: ["Gait", 'player:isSprinting() and "sprint" or player:isRunning() and "run" or "walk"'], needs: ["nudge"], lua: `if instanceof(who, "IsoPlayer") then
    -- no flight in Knox County: a second wind instead
    nudge(who, "ENDURANCE", 0.2)
    nudge(who, "FATIGUE", -0.05)
else
    who:setWalkType("sprint" .. tostring(ZombRand(3) + 1))
end` },
  void: { kind: "foe", outfit: "Priest", drop: "Base.Candle", part: "Base.Candle", hud: ["Panic", 'stat(player, "PANIC")'], needs: ["nudge"], lua: `if instanceof(target, "IsoPlayer") then
    nudge(target, "PANIC", 0.03 * power)
else
    target:setTarget(nil)
end` },
  lunar: { kind: "foe", outfit: "Nurse", drop: "Base.Torch", part: "Base.Candle", hud: ["Time", 'string.format("%02d:%02d", getGameTime():getHour(), getGameTime():getMinutes())'], needs: ["nudge", "hurt"], lua: `local hour = getGameTime():getHour()
if hour < 21 and hour >= 5 then return end
if instanceof(target, "IsoPlayer") then
    nudge(target, "FATIGUE", 0.04)
else
    hurt(target, power * 0.03, source)
end` },
  auto: { kind: "self", local: true, outfit: "ConstructionWorker", drop: "Base.Screwdriver", part: "Base.Wire", hud: ["Queue", "tostring(#ISTimedActionQueue.getTimedActionQueue(player).queue)"], lua: `if not instanceof(who, "IsoPlayer") or not who:isLocalPlayer() or ISTimedActionQueue.isPlayerDoingAction(who) then return end
local bag = who:getClothingItem_Back()
if not bag or not instanceof(bag, "InventoryContainer") then return end
-- vanilla transfer actions, so the server moves the items (MP-safe)
local inv, dest = who:getInventory(), bag:getItemContainer()
for i = inv:getItems():size() - 1, 0, -1 do
    local item = inv:getItems():get(i)
    if item:getCategory() == "Food" and not item:isFavorite() and not who:isEquipped(item) and dest:hasRoomFor(who, item) then
        ISTimedActionQueue.add(ISInventoryTransferAction:new(who, item, inv, dest))
    end
end` },
  neon: { kind: "self", local: true, outfit: "Punk", drop: "Base.LightBulb", part: "Base.LightBulb", hud: ["Stress", 'stat(player, "STRESS")'], lua: `if instanceof(who, "IsoPlayer") and who:isLocalPlayer() then
    who:setHaloNote(getTextOrNull("IGUI_$CLS_Proc") or "$NAME", $RGB, 250)
end` },
};

/** Item and NPC contexts summon decoys instead: useless "echoes" whose noise pulls the horde away. */
const ECHO = `local echoes = addZombiesInOutfit(square:getX(), square:getY(), square:getZ(), 2, "$OUTFIT", 50)
for i = 0, echoes:size() - 1 do
    echoes:get(i):setUseless(true)
    getWorldSoundManager():addSound(echoes:get(i), square:getX(), square:getY(), square:getZ(), math.floor(power * 3), 60)
end`;

const HELPERS: Record<NonNullable<FxDef["needs"]>[number], string> = {
  nudge: `--- B42 stats: getStats():add(CharacterStat.X, delta). A fraction of the stat's range; a no-op if the stat is missing.
local function nudge(character, name, fraction)
    local stat = CharacterStat and CharacterStat[name]
    if not stat then return end
    character:getStats():add(stat, (stat:getMaximumValue() - stat:getMinimumValue()) * fraction)
end`,
  hurt: `local function hurt(zombie, amount, source)
    zombie:setHealth(zombie:getHealth() - amount)
    if zombie:getHealth() <= 0 then zombie:Kill(source) end
end`,
  burn: `--- Fire only outdoors, away from buildings, water and safehouses, and only while the server allows it.
local function canBurn(square)
    if not Config.get("AllowFire") or not square:isOutside() or square:getBuilding() or square:isWaterSquare() or square:haveFire() then return false end
    return not (SafeHouse and SafeHouse.getSafeHouse(square))
end`,
};

const PLACES = [
  { name: "Muldraugh", x: 10630, y: 9560 },
  { name: "West Point", x: 11860, y: 6890 },
  { name: "Riverside", x: 6420, y: 5300 },
  { name: "Rosewood", x: 8080, y: 11650 },
  { name: "March Ridge", x: 10020, y: 12680 },
];
/** NPC role words -> vanilla outfit and what they trade. */
const ROLES: [RegExp, string, string[]][] = [
  [/doctor|medic|nurse|surgeon/, "Doctor", ["Base.Antibiotics", "Base.Bandage"]],
  [/mechanic|engineer/, "Mechanic", ["Base.EngineParts", "Base.Wrench"]],
  [/hunter|trapper/, "Hunter", ["Base.ShotgunShells", "Base.HuntingKnife"]],
  [/soldier|army|military/, "ArmyCamoGreen", ["Base.Bullets9mmBox", "Base.Bandage"]],
  [/sheriff|police|cop\b/, "Police", ["Base.Bullets9mmBox", "Base.Pills"]],
  [/priest|preacher/, "Priest", ["Base.Candle", "Base.Bandage"]],
  [/chef|cook/, "Chef", ["Base.CannedChili", "Base.TinnedBeans"]],
  [/farmer/, "Farmer", ["Base.Shovel", "Base.TinnedBeans"]],
];
const ORDINAL: Record<string, number> = { other: 2, second: 2, third: 3, fourth: 4, fifth: 5, sixth: 6, seventh: 7, eighth: 8, ninth: 9, tenth: 10 };

type Opt = [key: string, type: "boolean" | "integer" | "double" | "enum", def: number | boolean, min: number, max: number, label: string, tip: string, values?: string[]];
const val = (o: Opt, v: number | boolean = o[2]) => (o[1] === "double" && Number.isInteger(v) ? Number(v).toFixed(1) : String(v));
const GAP = " "; // a blank line inside `code` arrays
/** A PZ script block; nested blocks are just more strings. */
const blk = (head: string, body: (string | false)[]) => code`
  ${head}
  {
      ${body}
  }`;
const kv = (o: Record<string, string | number | boolean>) => Object.entries(o).map(([k, v]) => `${k} = ${v},`);
const json = (o: Record<string, string>) => `${JSON.stringify(o, null, 4)}\n`;
/** Lua string literal body: no quotes, backslashes or newlines can break out of it. */
const luaText = (s: string) => s.replace(/[\\"]/g, "").replace(/[\r\n]+/g, " ");

export function zomboidLua(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const arch = ARCH[k];
  const lite = input.model === "katara";
  const name = luaText(input.modName);
  const prompt = input.prompt.toLowerCase();
  const tint = fxs[0].tint.map((c) => Math.round(c * 255)).join(", ");
  const lead = FX[fxs[0].key];
  const has = (kind: Kind, where: "server" | "local" | "any" = "any") =>
    fxs.some((e) => FX[e.key].kind === kind && (where === "any" || (where === "local" ? !!FX[e.key].local : !FX[e.key].local)));
  const hasLocal = fxs.some((e) => FX[e.key].local);
  const hasServerFx = fxs.some((e) => !FX[e.key].local);
  const [L, S, TR] = [`${PZ_TARGET.versionFolder}/media/lua`, `${PZ_TARGET.versionFolder}/media/scripts/${snake}`, "common/media/lua/shared/Translate/EN"];
  const every = prompt.match(/every\s+(?:(\d+)(?:st|nd|rd|th)?|([a-z]+))\s+(?:night|day)/);
  const interval = Math.min(60, Number(every?.[1]) || ORDINAL[every?.[2] ?? ""] || n.interval);
  const horde = /horde|siren|alarm|wave|swarm|migrat|night/.test(prompt);
  const place = PLACES[hashStr(cls) % PLACES.length];
  const ui = new Map<string, string>([["Title", name]]);
  if (fxs.some((e) => e.key === "neon")) ui.set("Proc", name);
  /** UI strings: registered for IG_UI.json, read through txt() with an inline fallback. */
  const T = (key: string, text: string) => (ui.set(key, luaText(text)), `txt("${key}", "${luaText(text)}")`);
  const say = (key: string, text: string) => (ui.set(key, luaText(text)), `getTextOrNull("IGUI_${cls}_${key}") or "${luaText(text)}"`);
  const ITEM = `${cls}.${cls}`;
  const itemNames: Record<string, string> = {};
  const recipeNames: Record<string, string> = {};

  /* ── sandbox options: one list drives sandbox-options.txt, Sandbox.json and Config.Defaults ── */
  const ON: Opt = ["Enabled", "boolean", true, 0, 0, "Enabled", "Turns the mod on or off for this save without removing it."];
  const POWER: Opt = ["Power", "double", n.power, 0, 50, "Effect power", "Strength of every effect this mod applies."];
  const COOL = (label: string, def = n.cooldown): Opt => ["Cooldown", "double", def, 0, 120, label, "Real-time seconds before it can trigger again."];
  const RADIUS = (label: string): Opt => ["Radius", "integer", n.radius, 1, 30, label, "Measured in tiles."];
  const LOOT: Opt = ["LootWeight", "double", 1, 0, 10, "Loot weight", "Multiplier on how often it appears in containers."];
  const FIRE: Opt = ["AllowFire", "boolean", true, 0, 0, "Allow fire", "Fire effects can spread outdoors. They never start inside buildings or safehouses."];
  const int = (key: string, def: number, min: number, max: number, label: string, tip: string): Opt => [key, "integer", def, min, max, label, tip];
  const OPTS: Record<CategoryKey, Opt[]> = {
    weapons: [ON, ["Power", "double", n.power, 0, 50, "Bonus power", "Extra damage per hit and the strength of on-hit effects."], ["Chance", "double", n.chance, 0, 1, "Proc chance", "Chance that a hit triggers the special effect."], COOL("Proc cooldown (s)"), LOOT],
    items: [ON, POWER, RADIUS("Effect radius"), COOL("Recharge (s)"), LOOT],
    magic: [ON, POWER, RADIUS("Spell radius"), COOL("Recast (s)"), ["EnduranceCost", "double", n.chance, 0, 1, "Endurance cost", "Share of the endurance bar each cast costs."], LOOT],
    creatures: [ON, POWER, ["SpawnChance", "double", n.chance, 0, 1, "Pack chance", "Chance per night hour that a pack hunts each player."], int("PackSize", n.interval + 2, 1, 40, "Pack size", "Zombies per pack."), ["Health", "double", +(n.health / 300).toFixed(2), 0.1, 10, "Variant health", "1.0 is roughly a vanilla zombie."], ["WalkType", "enum", 3, 1, 3, "Variant speed", "How variants move once they wake up.", ["Shamblers", "Fast shamblers", "Sprinters"]], RADIUS("Ability range"), COOL("Ability cooldown (s)"), ["DropChance", "double", 0.25, 0, 1, "Drop chance", "Chance a variant carries something useful."]],
    characters: [ON, POWER, int("Price", Math.round(n.power), 1, 100, "Price (bills)", "Money a trade costs before discounts."), int("TradeCooldown", n.interval * 2, 0, 168, "Trade cooldown (hours)", "In-game hours between two trades."), RADIUS("Guard radius")],
    vehicles: [ON, POWER, int("SpawnChance", Math.max(1, Math.round(n.chance * 20)), 0, 100, "Spawn weight", "Weight per vehicle zone; vanilla cars sit around 1-20."), ["BoostMultiplier", "double", +(1 + n.intensity / 2).toFixed(2), 1, 4, "Boost multiplier", "Engine force while boosting."], int("Duration", n.duration, 1, 60, "Boost length (s)", "How long a boost lasts."), COOL("Boost cooldown (s)", +(n.cooldown * 4).toFixed(1))],
    worlds: [ON, POWER, ["LootMultiplier", "double", n.intensity, 0, 10, "Loot multiplier", "Scales the extra loot in local containers."], int("HazardMinutes", n.interval * 10, 10, 240, "Minutes between anomalies", "In-game minutes between anomalies inside the zone.")],
    mechanics: [ON, POWER, int("Interval", interval, 1, 60, "Nights between events", "The event fires on every Nth night survived."), int("StartHour", 22, 0, 23, "Start hour", "In-game hour the event starts."), int("Duration", Math.max(2, Math.round(n.duration / 2)), 1, 12, "Event length (hours)", "In-game hours before it ends."), ...(horde ? [int("HordeSize", Math.round(n.health / 10), 0, 500, "Horde size", "Zombies per player on the first event night."), int("HordeCap", 400, 0, 2000, "Horde cap", "Upper bound however long the save runs."), int("SirenRadius", n.radius * 25, 10, 300, "Siren radius", "Tiles from which zombies hear the sirens.")] : [])],
    quests: [ON, POWER, int("KillGoal", n.xp, 1, 500, "Kill goal", "Zombies to put down in stage two."), int("HoldMinutes", n.interval * 15, 10, 600, "Hold time (minutes)", "In-game minutes to hold the site."), int("SiteDistance", n.radius * 40, 20, 1000, "Site distance", "Tiles between the start and the site."), int("RewardXP", n.xp * 10, 0, 5000, "Reward XP", "Experience granted on completion."), RADIUS("Arrival radius")],
    interface: [ON, int("ScanRadius", n.radius * 4, 4, 60, "Scan radius", "Tiles the HUD scans for zombies."), int("DangerThreshold", n.interval, 1, 50, "Danger threshold", "Zombies in range per threat level.")],
    audio: [ON, int("ThreatRadius", n.radius * 3, 4, 60, "Threat radius", "Tiles counted when picking the layer."), int("CombatThreshold", n.interval, 1, 50, "Combat threshold", "Zombies in range that switch to the combat layer."), ["Volume", "double", 0.8, 0, 1, "Volume", "Peak gain of the music layers."], ["FadeSpeed", "double", +(0.2 + n.intensity / 4).toFixed(2), 0.05, 2, "Fade speed", "Gain per second when crossfading."]],
    shaders: [ON, ["Intensity", "double", n.intensity, 0, 2, "Intensity", "Blend between vanilla light and the grade."], ["Desaturation", "double", +(0.15 + n.chance).toFixed(2), 0, 1, "Desaturation", "How much colour drains out."], ["FogBoost", "double", +(n.chance / 2).toFixed(2), 0, 1, "Fog boost", "Extra fog on top of the weather."], ["NightOnly", "boolean", fxs.some((e) => e.key === "lunar"), 0, 0, "Night only", "Only grade between dusk and dawn."]],
  };
  // fire only matters where server effects can actually run
  const opts = [...OPTS[k], ...(fxs.some((e) => e.key === "fire") && !["interface", "audio", "shaders"].includes(k) ? [FIRE] : [])];
  const pad = Math.max(...opts.map((o) => o[0].length));
  const hasOpt = (key: string) => opts.some((o) => o[0] === key);

  /* ── shared/<Cls>/Config.lua: defaults plus the pure helpers the spec tests ── */
  const zone = { x: place.x - 40 - n.radius * 5, y: place.y - 30 - n.radius * 4, w: 80 + n.radius * 10, h: 60 + n.radius * 8 };
  const slot = arch === "entity" || arch === "system" ? k : arch;
  const CFG_HELPERS: Record<string, string> = {
    item: code`
      --- A worn item hits at half strength; area effects fall off linearly to the edge.
      function Config.scaled(power, condition, maxCondition) return power * (0.5 + 0.5 * Config.clamp(condition / math.max(1, maxCondition), 0, 1)) end
      function Config.falloff(distance, radius) return radius > 0 and Config.clamp(1 - distance / radius, 0, 1) or 0 end`,
    creatures: code`
      --- Rolled from the persistent outfit ID, so the server and every client agree on which zombie is a variant.
      function Config.isVariant(outfitId, chance) return outfitId ~= nil and (math.abs(outfitId) % 1000) < chance * 1000 end

      local GAITS = { "slow", "", "sprint" }
      --- WalkType enum -> IsoZombie walk type: "slow1".."slow3", "1".."5" or "sprint1".."sprint5".
      function Config.walkType(mode, seed)
          local prefix = GAITS[Config.clamp(mode, 1, 3)]
          return prefix .. tostring(math.abs(seed) % (prefix == "slow" and 3 or 5) + 1)
      end`,
    characters: code`
      function Config.canTrade(lastHours, nowHours, cooldownHours) return lastHours == nil or nowHours - lastHours >= cooldownHours end
      --- Regulars get a discount: one bill off per 100 kills, never below 1.
      function Config.price(base, kills) return math.max(1, base - math.floor(kills / 100)) end`,
    vehicles: code`
      --- A wrecked engine (condition 0) gets no boost at all.
      function Config.boostForce(baseForce, multiplier, condition) return math.floor(baseForce * (1 + (multiplier - 1) * Config.clamp(condition / 100, 0, 1))) end`,
    world: code`
      -- Near ${place.name}: ${zone.x},${zone.y} to ${zone.x + zone.w},${zone.y + zone.h}
      Config.Zone = { name = "${cls}", x = ${zone.x}, y = ${zone.y}, z = 0, w = ${zone.w}, h = ${zone.h} }

      function Config.inZone(x, y, area)
          area = area or Config.Zone
          return x >= area.x and x < area.x + area.w and y >= area.y and y < area.y + area.h
      end`,
    mechanics: code`
      --- Night 0 never counts; after that every Interval-th night is an event night.
      function Config.isEventNight(nights, interval) return interval > 0 and nights > 0 and nights % interval == 0 end
      --- Every event survived adds a quarter of the base horde, up to the cap.
      function Config.hordeSize(base, nights, interval, cap)
          local waves = math.floor(nights / math.max(1, interval))
          return math.min(cap, base + math.max(0, waves - 1) * math.ceil(base / 4))
      end`,
    quests: code`
      Config.Stages = { { id = "Gear", goal = 1 }, { id = "Cull", goal = "KillGoal" }, { id = "Reach", goal = 1 }, { id = "Hold", goal = "HoldMinutes" } }

      --- Numbers are literal goals, strings name a sandbox option.
      function Config.goal(stage) return type(stage.goal) == "string" and Config.get(stage.goal) or stage.goal end
      function Config.advance(index, progress)
          local stage = Config.Stages[index]
          return (stage and progress >= Config.goal(stage)) and index + 1 or index
      end`,
    interface: code`
