      function Config.layerFor(zombies, isNight, threshold)
          if zombies >= threshold then return "Combat" end
          return (zombies > 0 or isNight) and "Tension" or "Calm"
      end
      function Config.approach(current, target, step) return current < target and math.min(target, current + step) or math.max(target, current - step) end`,
    visual: code`
