    fxs.some((e) => FX[e.key].kind === kind && (where === "any" || (where === "local" ? !!FX[e.key].local : !FX[e.key].local)));
  const hasLocal = fxs.some((e) => FX[e.key].local);
  const hasServerFx = fxs.some((e) => !FX[e.key].local);
  const [L, S, TR] = [`${PZ_TARGET.versionFolder}/media/lua`, `${PZ_TARGET.versionFolder}/media/scripts/${snake}`, "common/media/lua/shared/Translate/EN"];
  const every = prompt.match(/every\s+(?:(\d+)(?:st|nd|rd|th)?|([a-z]+))\s+(?:night|day)/);
  const interval = Math.min(60, Number(every?.[1]) || ORDINAL[every?.[2] ?? ""] || n.interval);
  const horde = /horde|siren|alarm|wave|swarm|migrat|night/.test(prompt);
