        ${input.modName} · ${role}
        ${input.category.label} mod for Project Zomboid Build ${PZ_TARGET.versionFolder} (${PZ_TARGET.versionMin}+) · forged by Cyrus (${MODEL_NAME[input.model]}) v${input.version}
    ]]
    ${input.version > 1 ? `-- v${input.version}: retuned defaults; every number now lives in sandbox options` : ""}`;
  const REQ = (mod: "Config" | "Effects") => `local ${mod} = require("${cls}/${mod}")`;
  /** `local power` only when a call site actually uses it. */
  const pw = (lines: string[], expr = 'Config.get("Power")') => (lines.length ? [`local power = ${expr}`, ...lines] : []);
  const STATE = code`
    local function state(obj)
        local md = obj:getModData()
        md[MOD] = md[MOD] or {}
        return md[MOD]
    end`;
  const TXT = `local function txt(key, fallback) return getTextOrNull("IGUI_${cls}_" .. key) or fallback end`;
  const sub = (s: string, outfit = lead.outfit) => s.replaceAll("$CLS", cls).replaceAll("$NAME", name).replaceAll("$RGB", tint).replaceAll("$OUTFIT", outfit);

  /** Server-authoritative effect table (shared/Effects.lua). `echo` swaps summon for decoys. */
  const echo = arch === "item" || k === "characters";
  const serverFx = fxs.filter((e) => !FX[e.key].local);
  const needs = new Set(serverFx.flatMap((e) => FX[e.key].needs ?? []));
  const effectsBody = code`
    local Effects = { Fx = {}, WorldFx = {} }
    local Fx, WorldFx = Effects.Fx, Effects.WorldFx

    ${[...needs].map((h) => HELPERS[h]).join("\n\n")}
    ${serverFx
      .map((e) => code`

        --- ${e.label}
        function ${FX[e.key].kind === "world" ? "WorldFx" : "Fx"}.${e.key}(${({ foe: "target, source, power", self: "who, power", world: "square, source, power" })[FX[e.key].kind]})
            ${sub(e.key === "summon" && echo ? ECHO : FX[e.key].lua)}
        end`)
      .join("")}

    --- The zombie a client pointed at: matched by online ID when there is one, else the nearest within 2 tiles.
    function Effects.findZombie(x, y, z, zid)
        local best, bestDist
        for dx = -2, 2 do
            for dy = -2, 2 do
                local square = getCell():getGridSquare(x + dx, y + dy, z)
                local movers = square and square:getMovingObjects()
                for i = 0, movers and movers:size() - 1 or -1 do
                    local obj = movers:get(i)
                    if instanceof(obj, "IsoZombie") and not obj:isDead() then
                        if zid and zid >= 0 and obj:getOnlineID() == zid then return obj end
                        local dist = IsoUtils.DistanceTo(x, y, obj:getX(), obj:getY())
                        if not bestDist or dist < bestDist then best, bestDist = obj, dist end
                    end
                end
            end
        end
        return best
    end

    --- Applies every server effect of this mod: foe effects to the target, self effects to the source, world effects at the target's square.
    function Effects.hit(target, source, power)
        ${serverFx.map((e) => (FX[e.key].kind === "foe" ? `Fx.${e.key}(target, source, power)` : FX[e.key].kind === "self" ? `Fx.${e.key}(source, power)` : `local square${e.key} = target:getCurrentSquare()\nif square${e.key} then WorldFx.${e.key}(square${e.key}, source, power) end`))}
    end`;
  /** Client-only effects (UI and vanilla timed actions). */
  const localFx = fxs.filter((e) => FX[e.key].local);
  const localBody = localFx.length
    ? code`
      local Local = {}
      ${localFx.map((e) => code`

        --- ${e.label}
        function Local.${e.key}(who, power)
            ${sub(FX[e.key].lua)}
        end`).join("")}`
    : "";
  const localCalls = (who: string) => localFx.map((e) => `Local.${e.key}(${who}, power)`);

  const REQUEST = code`
    --- Game-state changes are the server's job in Build 42; in singleplayer the command loops straight back.
    local function request(player, command, target, extra)
        local args = extra or {}
        target = target or player
        args.x, args.y, args.z = math.floor(target:getX()), math.floor(target:getY()), math.floor(target:getZ())
        if instanceof(target, "IsoZombie") then args.zid = target:getOnlineID() end
        sendClientCommand(player, MOD, command, args)
    end`;
  const ROUTER = (commands: string) => code`
    local Commands = {}
    local last = {}

    --- Server-side rate limit per player and action, so a modified client cannot spam effects.
    local function allow(player, action, seconds)
        local key, now = player:getUsername() .. ":" .. action, getTimestampMs()
        if last[key] and now - last[key] < seconds * 1000 then return false end
        last[key] = now
        return true
    end

    ${commands}

    Events.OnClientCommand.Add(function(module, command, player, args)
        if module ~= MOD or not Commands[command] or type(args) ~= "table" or not Config.get("Enabled") then return end
        -- never trust a client blindly: whatever it points at has to be near the sender
        if not args.x or not args.y or IsoUtils.DistanceTo(player:getX(), player:getY(), args.x, args.y) > 30 then return end
        Commands[command](player, args)
    end)`;
  const PLAYERS = code`
    local function forEachPlayer(fn)
        local online = isServer() and getOnlinePlayers()
        for i = 0, online and online:size() - 1 or getNumActivePlayers() - 1 do
