    local function ${id}Key()
        local option = options and options:getOption("${id}")
        return option and option:getValue() or Keyboard.${key}
    end`;
  /** loop: ambient bed · world: positional, zombies-can-hear-it range · ui: flat one-shot. Clips live in common/media/sound/<Cls>/. */
