    defs.forEach(([id]) => assets.push(`common/media/sound/${cls}/${id.toLowerCase()}.ogg`));
    return file(`${S}/sounds.txt`, blk("module Base", defs.flatMap(([id, kind], i) => [i ? GAP : false, blk(`sound ${cls}_${id}`, [
      ...kv(SOUND[kind][0]),
      blk("clip", kv({ file: `media/sound/${cls}/${id.toLowerCase()}.ogg`, ...SOUND[kind][1] })),
    ])])));
  };

  /* Each archetype fills these; assembly below turns them into files (or one file for Katara). */
  let clientSrc = "";
  let serverSrc = "";
  let actionsSrc = "";
  const clientRequires: string[] = [];
  const serverRequires: string[] = [];
  const extraClient: ModFile[] = []; // UI panels (full output only)
  let scripts: ModFile[] = [];
  let useEffects = hasServerFx;

  if (arch === "item") {
