    const weapon = k === "weapons";
    const magic = k === "magic";
    const axe = /axe|hatchet|cleav|blade|sword|katana|machete/.test(prompt);
    const snd = axe ? "Axe" : "BaseballBat";
    const minD = +(0.6 + n.power / 14).toFixed(2);
