    assets.push(`common/media/textures/Item_${cls}.png (inventory icon)`, `common/media/models_X/${mesh}.fbx`, `common/media/textures/${mesh}.png`);
    itemNames[ITEM] = name;
    recipeNames[`Make${cls}`] = `Make ${name}`;
    const props: Record<string, string | number> = weapon
      ? { DisplayCategory: "Weapon", ItemType: "base:weapon", WeaponSprite: cls, Weight: (1.5 + n.radius / 4).toFixed(1), Categories: axe ? "base:axe" : "base:blunt", SubCategory: "Swinging", TwoHandWeapon: "TRUE",
          MinDamage: minD, MaxDamage: +(minD + 0.5 + n.intensity / 2).toFixed(2), MinRange: 0.61, MaxRange: (1.15 + n.chance).toFixed(2), MinAngle: 0.72, Swingtime: (1.5 + n.cooldown / 8).toFixed(1), MinimumSwingtime: 1.5, SwingAmountBeforeImpact: 0.02, BaseSpeed: 1,
          MaxHitcount: n.radius > 6 ? 3 : 2, CriticalChance: Math.round(n.chance * 100), CritDmgMultiplier: 2, KnockBackOnNoDeath: "TRUE", PushBackMod: 0.3, SplatNumber: 2, SplatBloodOnNoDeath: "TRUE",
          ...(axe ? { DamageCategory: "Slash", DamageMakeHole: "TRUE", TreeDamage: 25 } : {}), DoorDamage: Math.round(n.power), ConditionMax: 10 + n.interval, ConditionLowerChanceOneIn: 8 + n.interval,
          SwingAnim: "Bat", IdleAnim: "Idle_Weapon2", RunAnim: "Run_Weapon2", SwingSound: `${snd}Swing`, HitSound: `${snd}Hit`, HitFloorSound: `${snd}Hit`, DoorHitSound: `${snd}Hit`, BreakSound: `${snd}Break`, AttachmentType: axe ? "BigBlade" : "BigWeapon" }
      : magic
        ? { DisplayCategory: "Junk", ItemType: "base:normal", Weight: 0.2, ConditionMax: 10 + n.interval, StaticModel: cls, WorldStaticModel: cls }
        : { DisplayCategory: "Tool", ItemType: "base:drainable", Weight: (0.6 + n.intensity / 2).toFixed(1), UseDelta: (1 / (n.interval + 4)).toFixed(3), UseWhileEquipped: "FALSE", cantBeConsolided: "TRUE", StaticModel: cls, WorldStaticModel: cls };
    const script = file(`${S}/items.txt`, blk(`module ${cls}`, [
