        IS${cls}Action = ISBaseTimedAction:derive("IS${cls}Action")

        function IS${cls}Action:isValid() return self.character:getInventory():contains(self.item) end
        function IS${cls}Action:waitToStart() return false end

        function IS${cls}Action:update()
            self.item:setJobDelta(self:getJobDelta())
            self.character:setMetabolicTarget(Metabolics.LightWork)
        end

        function IS${cls}Action:start()
            self.item:setJobType(${say(magic ? "Casting" : "Use", magic ? "Channelling" : "Activate")})
            self:setActionAnim(CharacterActionAnims.Craft)
            self:setOverrideHandModels(self.item, nil)
        end

        function IS${cls}Action:stop()
            self.item:setJobDelta(0.0)
            ISBaseTimedAction.stop(self)
        end

        --- Client and SP: sound, UI, the local-only effects. No item or world changes here.
        function IS${cls}Action:perform()
            self.item:setJobDelta(0.0)
            ${localFx.length ? pw(localCalls("self.character")) : ""}
            self.character:setHaloNote(${say("Done", `${name}: done`)}, ${tint}, 250)
            ISBaseTimedAction.perform(self)
        end

        --- Server and SP: every zombie in range takes the hit, strongest at the centre; then the item wears.
        function IS${cls}Action:complete()
            local base, radius = Config.get("Power"), Config.get("Radius")
            local zombies = getCell():getZombieList()
            for i = zombies:size() - 1, 0, -1 do
                local zombie = zombies:get(i)
                local dist = zombie:DistTo(self.character)
                if dist <= radius and not zombie:isDead() then Effects.hit(zombie, self.character, base * Config.falloff(dist, radius)) end
            end
            ${magic
              ? code`
                self.item:setCondition(math.max(0, self.item:getCondition() - 1))
                syncItemFields(self.character, self.item)`
              : "self.item:UseAndSync()"}
            return true
        end

        function IS${cls}Action:getDuration() return self.character:isTimedActionInstant() and 1 or ${Math.round(40 + n.cooldown * 15)} end

        --- Argument names match the fields so the server can rebuild the action (42.13 MP rules).
        function IS${cls}Action:new(character, item)
            local o = ISBaseTimedAction.new(self, character)
            o.item = item
            o.stopOnWalk = ${String(magic)}
            o.stopOnRun = true
            o.maxTime = o:getDuration()
            return o
        end`;
      clientRequires.push('require "TimedActions/ISTimedActionQueue"');
