      end

      ${ROUTER(code`
        --- A variant's ability, aimed at the player who reported it; the server re-checks variant, range and cooldown.
        function Commands.ability(player, args)
            local zombie = Effects.findZombie(args.x, args.y, args.z, args.zid)
