/**
 * Static validator for generated Project Zomboid (Build 42) mods (PURE, client-safe, no I/O).
 *
 * What it checks, without the game (see lib/cyrus/games/zomboid.ts `verification`):
 *   1. layout: one mod.info in a version folder (or common/), code under 42/media, no Build 41 root media/,
 *      safe relative paths, per-mod Lua subfolders
 *   2. mod.info: id, name, versionMin >= the Cyrus minimum, plain MOD_IDs in require/incompatible
 *   3. Lua 5.1 structure: strings, long strings, comments, block keywords and brackets all balance
 *   4. dangerous APIs (GameSupport.dangerousApis) on comment-stripped Lua; obfuscation on the raw text
 *   5. the Build 41 -> 42 failure rules (GameSupport.knowledge.failureRules) on every file
 *   6. multiplayer rules: timed actions in shared/ with getDuration() and complete(), no item creation in client/
 *   7. script files (items, recipes, vehicles, sounds, sandbox options): braces balance, module wrapper
 *   8. translations: valid JSON objects of strings with the right key prefixes
 *
 * It cannot prove the mod does what the prompt asked or that every Java call exists (that needs a
 * load test on a real server, see READINESS.md); it catches the ways generated code most often breaks.
 */
import support, { PZ_TARGET } from "./zomboid";

export type ZomboidFile = { path: string; content: string };
export type ZomboidIssue = { severity: "block" | "warn"; rule: string; file?: string; line?: number; message: string };
export type ZomboidReport = { ok: boolean; issues: ZomboidIssue[]; modId: string | null };

/* ───────────── Lua 5.1 lexer (enough to find structure, strings and comments) ───────────── */

type Tok = { t: "name" | "kw" | "str" | "num" | "op"; v: string; line: number };
const KEYWORDS = new Set(["and", "break", "do", "else", "elseif", "end", "false", "for", "function", "if", "in", "local", "nil", "not", "or", "repeat", "return", "then", "true", "until", "while"]);

/** Length of a long bracket opener at i (`[[`, `[==[`), or -1. */
function longOpen(src: string, i: number): number {
  if (src[i] !== "[") return -1;
  let j = i + 1;
  while (src[j] === "=") j++;
  return src[j] === "[" ? j - i - 1 : -1;
}

export function lexLua(src: string): { tokens: Tok[]; errors: { line: number; message: string }[]; code: string } {
  const tokens: Tok[] = [];
  const errors: { line: number; message: string }[] = [];
  let code = ""; // the source with comments blanked out (strings kept), for API matching
  let line = 1;
  let i = 0;
  const n = src.length;
  const keep = (from: number, to: number) => (code += src.slice(from, to));
  const blank = (from: number, to: number) => (code += src.slice(from, to).replace(/[^\n]/g, " "));
  while (i < n) {
    const c = src[i];
    if (c === "\n") { line++; keep(i, i + 1); i++; continue; }
    if (c === " " || c === "\t" || c === "\r") { keep(i, i + 1); i++; continue; }
    // comments
    if (c === "-" && src[i + 1] === "-") {
      const start = i;
      const lvl = longOpen(src, i + 2);
      if (lvl >= 0) {
        const close = `]${"=".repeat(lvl)}]`;
        const endAt = src.indexOf(close, i + 4 + lvl);
        if (endAt < 0) { errors.push({ line, message: "unterminated long comment" }); blank(start, n); break; }
        const chunk = src.slice(i, endAt + close.length);
        line += (chunk.match(/\n/g) ?? []).length;
        i = endAt + close.length;
      } else {
        while (i < n && src[i] !== "\n") i++;
      }
      blank(start, i);
      continue;
    }
    // long strings
    const lvl = longOpen(src, i);
    if (lvl >= 0) {
      const close = `]${"=".repeat(lvl)}]`;
      const endAt = src.indexOf(close, i + 2 + lvl);
      if (endAt < 0) { errors.push({ line, message: "unterminated long string" }); keep(i, n); break; }
      const chunk = src.slice(i, endAt + close.length);
      tokens.push({ t: "str", v: chunk, line });
      line += (chunk.match(/\n/g) ?? []).length;
      keep(i, endAt + close.length);
      i = endAt + close.length;
      continue;
    }
    // quoted strings
    if (c === '"' || c === "'") {
      const start = i;
      i++;
      let closed = false;
      while (i < n) {
        if (src[i] === "\\") { i += 2; continue; }
        if (src[i] === "\n") break;
        if (src[i] === c) { closed = true; i++; break; }
        i++;
      }
      if (!closed) errors.push({ line, message: "unterminated string" });
      tokens.push({ t: "str", v: src.slice(start, i), line });
      keep(start, i);
      continue;
    }
    // numbers
    if (/[0-9]/.test(c) || (c === "." && /[0-9]/.test(src[i + 1] ?? ""))) {
      const m = /^(0[xX][0-9a-fA-F]+|[0-9]*\.?[0-9]+([eE][+-]?[0-9]+)?)/.exec(src.slice(i))!;
      tokens.push({ t: "num", v: m[0], line });
      keep(i, i + m[0].length);
      i += m[0].length;
      continue;
    }
    // names / keywords
    if (/[A-Za-z_]/.test(c)) {
      const m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(src.slice(i))!;
      tokens.push({ t: KEYWORDS.has(m[0]) ? "kw" : "name", v: m[0], line });
      keep(i, i + m[0].length);
      i += m[0].length;
      continue;
    }
    // operators
    const op = /^(\.\.\.|\.\.|==|~=|<=|>=|[-+*/%^#<>=(){}[\];:,.])/.exec(src.slice(i));
    if (!op) { errors.push({ line, message: `unexpected character '${c}'` }); keep(i, i + 1); i++; continue; }
    tokens.push({ t: "op", v: op[0], line });
    keep(i, i + op[0].length);
    i += op[0].length;
  }
  return { tokens, errors, code };
}

/** Block and bracket balance for Lua 5.1. Returns human-readable problems (empty = structurally sound). */
export function luaStructure(src: string): { line: number; message: string }[] {
  const { tokens, errors } = lexLua(src);
  const out = [...errors];
  const blocks: { kw: string; line: number }[] = [];
  const brackets: { ch: string; line: number }[] = [];
  let pendingDo = 0; // `for`/`while` own the next `do`
  const pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
  for (const tk of tokens) {
    if (tk.t === "op") {
      if (tk.v === "(" || tk.v === "[" || tk.v === "{") brackets.push({ ch: tk.v, line: tk.line });
      else if (tk.v in pairs) {
        const top = brackets.pop();
        if (!top || top.ch !== pairs[tk.v]) out.push({ line: tk.line, message: `unmatched '${tk.v}'` });
      }
      continue;
    }
    if (tk.t !== "kw") continue;
    switch (tk.v) {
      case "function":
      case "if":
        blocks.push({ kw: tk.v, line: tk.line });
        break;
      case "for":
      case "while":
        blocks.push({ kw: tk.v, line: tk.line });
        pendingDo++;
        break;
      case "do":
        if (pendingDo > 0) pendingDo--;
        else blocks.push({ kw: "do", line: tk.line });
        break;
      case "repeat":
        blocks.push({ kw: "repeat", line: tk.line });
        break;
      case "elseif":
      case "else": {
        const top = blocks[blocks.length - 1];
        if (!top || top.kw !== "if") out.push({ line: tk.line, message: `'${tk.v}' outside an if block` });
        break;
      }
      case "until": {
        const top = blocks.pop();
        if (!top || top.kw !== "repeat") out.push({ line: tk.line, message: "'until' without 'repeat'" });
        break;
      }
      case "end": {
        const top = blocks.pop();
        if (!top) out.push({ line: tk.line, message: "'end' with no open block" });
        else if (top.kw === "repeat") out.push({ line: tk.line, message: `'repeat' (line ${top.line}) closed with 'end' instead of 'until'` });
        break;
      }
    }
  }
  for (const b of blocks) out.push({ line: b.line, message: `'${b.kw}' is never closed` });
  for (const b of brackets) out.push({ line: b.line, message: `'${b.ch}' is never closed` });
  if (pendingDo > 0) out.push({ line: tokens[tokens.length - 1]?.line ?? 1, message: "'for'/'while' without 'do'" });
  return out;
}

/* ───────────── script files (items, recipes, vehicles, sounds, sandbox options) ───────────── */

export function scriptStructure(src: string): { line: number; message: string }[] {
  const out: { line: number; message: string }[] = [];
  const text = src.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, " "));
  let depth = 0;
  text.split("\n").forEach((raw, idx) => {
    const ln = raw.trim();
    for (const ch of ln) {
      if (ch === "{") depth++;
      if (ch === "}") { depth--; if (depth < 0) { out.push({ line: idx + 1, message: "unmatched '}'" }); depth = 0; } }
    }
    if (depth > 0 && /^[A-Za-z_][\w.]*\s*=\s*\S/.test(ln) && !ln.endsWith(",")) out.push({ line: idx + 1, message: "property line must end with ','" });
  });
  if (depth > 0) out.push({ line: text.split("\n").length, message: `${depth} block(s) never closed` });
  return out;
}

/* ───────────── helpers ───────────── */

const lineOf = (s: string, index: number) => s.slice(0, index).split("\n").length;
const isLua = (p: string) => p.endsWith(".lua");
const isScript = (p: string) => /^42(\.\d+)?\/media\/scripts\/.+\.txt$/.test(p);
const isSandbox = (p: string) => /^42(\.\d+)?\/media\/sandbox-options\.txt$/.test(p);
const isTranslation = (p: string) => /\/media\/lua\/shared\/Translate\/[A-Z]{2,4}\//.test(p);
const ROOT_OK = /^(42(\.\d+){0,2}|common)\/|^tests\/[^/]+_spec\.lua$|^(README|CHANGELOG|ASSETS)\.md$/;
const TRANSLATION_PREFIX: Record<string, RegExp> = { IG_UI: /^IGUI_/, Sandbox: /^Sandbox_/, Tooltip: /^Tooltip_/, ContextMenu: /^ContextMenu_/, UI: /^UI_/ };

function cmpVersion(a: string, b: string) {
  const pa = a.split(".").map(Number), pb = b.split(".").map(Number);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] ?? 0) - (pb[i] ?? 0);
    if (d) return d;
  }
  return 0;
}

export function parseModInfo(src: string): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const raw of src.split(/\r?\n/)) {
    const m = /^\s*([A-Za-z]+)\s*=\s*(.*?)\s*$/.exec(raw);
    if (m) (out[m[1]] ??= []).push(m[2]);
  }
  return out;
}

const DANGEROUS = support.dangerousApis.map((d) => ({ ...d, re: new RegExp(d.pattern, "g") }));
const OBFUSCATION = DANGEROUS.filter((d) => d.why.startsWith("Obfuscated"));
const RULES = (support.knowledge?.failureRules ?? []).map((r) => ({ ...r, re: new RegExp(r.detect, "m") }));

/* ───────────── the validator ───────────── */

export function validateZomboidMod(files: ZomboidFile[]): ZomboidReport {
  const issues: ZomboidIssue[] = [];
  const add = (severity: ZomboidIssue["severity"], rule: string, message: string, file?: string, line?: number) => issues.push({ severity, rule, message, file, line });

  /* 1. layout */
  for (const f of files) {
    if (f.path.startsWith("/") || /(^|\/)\.\.(\/|$)/.test(f.path) || f.path.includes("\\")) add("block", "path", "File paths must be relative, forward-slash and stay inside the mod folder.", f.path);
    else if (/^media\//.test(f.path)) add("block", "b41-layout", "Build 41 layout: Build 42 ignores a root-level media/ folder. Put code under 42/media and assets under common/media.", f.path);
    else if (!ROOT_OK.test(f.path)) add("warn", "path", "Unexpected top-level file or folder; the game ignores it.", f.path);
    if (/^(42[^/]*|common)\/Media\//.test(f.path) || /\/Lua\/|\/Scripts\//.test(f.path)) add("block", "case", "Folder names are case-sensitive on Linux servers: use media/, lua/, scripts/.", f.path);
  }
  const infos = files.filter((f) => /^(42(\.\d+){0,2}|common)\/mod\.info$/.test(f.path));
  let modId: string | null = null;
  if (!infos.length) add("block", "mod.info", "No mod.info in a version folder (42/) or common/: the game will not list the mod.");
  for (const info of infos) {
    const kv = parseModInfo(info.content);
    const id = kv.id?.[0];
    if (!id) add("block", "mod.info", "mod.info has no id.", info.path);
    else if (!/^[A-Za-z0-9_.-]+$/.test(id)) add("block", "mod.info", `mod.info id "${id}" may only use letters, digits, '_', '-' and '.'.`, info.path);
    else modId ??= id;
    if (!kv.name?.[0]) add("block", "mod.info", "mod.info has no name.", info.path);
    const min = kv.versionMin?.[0];
    if (!min) add("block", "mod.info", `mod.info needs versionMin (at least ${PZ_TARGET.versionMin}) so older builds do not try to load it.`, info.path);
    else if (!/^\d+\.\d+(\.\d+)?$/.test(min)) add("block", "mod.info", "versionMin must look like build.major, e.g. 42.15.", info.path);
    else if (cmpVersion(min, PZ_TARGET.versionMin) < 0) add("block", "mod.info", `versionMin ${min} is older than ${PZ_TARGET.versionMin}; JSON translations need 42.15+.`, info.path);
    const max = kv.versionMax?.[0];
    if (max && cmpVersion(max, PZ_TARGET.testedOn) < 0) add("warn", "outdated", `versionMax ${max} is below the current stable ${PZ_TARGET.testedOn}; the game will refuse the mod.`, info.path);
    if (!kv.modversion?.[0]) add("warn", "mod.info", "mod.info has no modversion, so updates cannot be told apart.", info.path);
    for (const key of ["require", "incompatible", "loadModAfter", "loadModBefore"]) {
      for (const v of kv[key] ?? []) if (v.includes("\\")) add("warn", "backslash-mod-id", `${key}= should list plain MOD_IDs (42.15), without '\\'.`, info.path);
    }
    for (const key of ["poster", "icon"]) {
      for (const v of kv[key] ?? []) {
        const dir = info.path.slice(0, info.path.lastIndexOf("/") + 1);
        if (!files.some((f) => f.path === dir + v)) add("warn", "asset", `mod.info ${key}=${v} is not in the project; the mod manager shows no image.`, info.path);
      }
    }
  }
  const codeFiles = files.filter((f) => isLua(f.path) && /^42[^/]*\/media\/lua\/(client|server|shared)\//.test(f.path));
  if (!codeFiles.length && !files.some((f) => isScript(f.path))) add("block", "entry", "No Lua under 42/media/lua/{client,server,shared} and no script files: the mod does nothing.");
  for (const f of codeFiles) {
    if (modId && !new RegExp(`/lua/(client|server|shared)/${modId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}/`).test(f.path)) add("warn", "load-order", `Keep Lua in a folder named after the mod (lua/<side>/${modId}/) so it cannot overwrite another mod's file.`, f.path);
  }

  /* 3–6. Lua */
  for (const f of files.filter((x) => isLua(x.path))) {
    for (const e of luaStructure(f.content)) add("block", "lua-syntax", e.message, f.path, e.line);
    const { code } = lexLua(f.content);
    for (const d of DANGEROUS) {
      const src = OBFUSCATION.includes(d) ? f.content : code;
      d.re.lastIndex = 0;
      const m = d.re.exec(src);
      if (m) add(d.severity, "dangerous-api", `${m[0].trim()}: ${d.why}`, f.path, lineOf(src, m.index));
    }
    // mod files are allowed only inside the mod's own folder, with a plain relative path
    for (const m of code.matchAll(/getModFile(Writer|Reader)\s*\(\s*([^,)]+)\s*,\s*"([^"]*)"/g)) {
      if (/^[/\\]|\.\./.test(m[3]) || (modId && !m[2].includes("MOD") && !m[2].includes(`"${modId}"`))) add("block", "file-access", "getModFileWriter/Reader may only touch this mod's own folder with a relative path.", f.path, lineOf(code, m.index!));
    }
    if (/\bISBaseTimedAction\s*:\s*derive\b/.test(code)) {
      if (!/\/media\/lua\/shared\//.test(f.path)) add("block", "mp-timed-action", "Timed actions must live in media/lua/shared so the server can rebuild them (42.13).", f.path);
      for (const m of code.matchAll(/(\w+)\s*=\s*ISBaseTimedAction\s*:\s*derive/g)) {
        for (const fn of ["getDuration", "complete"]) if (!new RegExp(`function\\s+${m[1]}\\s*:\\s*${fn}\\s*\\(`).test(code)) add("block", "mp-timed-action", `${m[1]} has no ${fn}(); Build 42 multiplayer needs it.`, f.path);
      }
    }
    if (/\/media\/lua\/client\//.test(f.path) && /:\s*AddItem\s*\(|\binstanceItem\s*\(/.test(code)) add("block", "mp-items", "Items are created on the server in Build 42 multiplayer; this client-side item is deleted on relog.", f.path);
  }

  /* 5. failure rules (all files, path + content) */
  for (const f of files) {
    const hay = `${f.path}\n${f.content}`;
    for (const r of RULES) {
      const m = r.re.exec(hay);
      if (m && !issues.some((x) => x.rule === r.id && x.file === f.path)) add("block", r.id, `${r.why} Fix: ${r.fix}`, f.path, Math.max(1, lineOf(hay, m.index) - 1));
    }
  }

  /* 7. script files */
  for (const f of files.filter((x) => isScript(x.path) || isSandbox(x.path))) {
    for (const e of scriptStructure(f.content)) add("block", "script-syntax", e.message, f.path, e.line);
    if (isScript(f.path) && !/^\s*(\/\*[\s\S]*?\*\/\s*)*module\s+\w+\s*\{/.test(f.content)) add("block", "script-syntax", "Script files must wrap their blocks in `module <Name> { … }`.", f.path);
    if (isSandbox(f.path) && !/^\s*VERSION\s*=\s*1\s*,/m.test(f.content)) add("block", "script-syntax", "sandbox-options.txt must start with `VERSION = 1,`.", f.path);
    if (/^\s*item\s+\w+/m.test(f.content) && !/ItemType\s*=\s*base:\w+/.test(f.content)) add("block", "item-type-field", "Every Build 42 item needs ItemType = base:…", f.path);
  }

  /* 8. translations */
  for (const f of files.filter((x) => isTranslation(x.path))) {
    if (!f.path.endsWith(".json")) continue; // .txt is caught by the txt-translations rule
    let data: unknown;
    try { data = JSON.parse(f.content); } catch { add("block", "translation", "Not valid JSON; every string in this file falls back to its key.", f.path); continue; }
    if (!data || typeof data !== "object" || Array.isArray(data)) { add("block", "translation", "A translation file must be a JSON object of key: text.", f.path); continue; }
    const type = f.path.slice(f.path.lastIndexOf("/") + 1, -5);
    for (const [key, v] of Object.entries(data as Record<string, unknown>)) {
      if (key === "$schema") continue;
      if (typeof v !== "string") add("block", "translation", `"${key}" must map to a string.`, f.path);
      const prefix = TRANSLATION_PREFIX[type];
      if (prefix && !prefix.test(key)) add("warn", "translation", `"${key}" should start with ${prefix.source.slice(1)} in ${type}.json.`, f.path);
    }
  }

  return { ok: !issues.some((x) => x.severity === "block"), issues, modId };
}

