// Project Zomboid support for Cyrus: the GameSupport facts, the Build 42 generator and the static validator.
// Pure: no DB, no network, no game files. Run: tsx --test test/cyrus-game-zomboid.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import support, { PZ_TARGET } from "../lib/cyrus/games/zomboid";
import { luaStructure, parseModInfo, scriptStructure, validateZomboidMod, type ZomboidFile } from "../lib/cyrus/games/zomboid.validate";
import { buildModFiles } from "../lib/cyrus/engine/templates";
import { zomboidLua } from "../lib/cyrus/engine/games/zomboid";
import { CATEGORIES, GAME_BY_ID } from "../lib/cyrus/data";
import type { CategoryKey, ModelId } from "../lib/cyrus/types";

/** The universal category ids (lib/cyrus/categories.ts on feature/cyrus-v6-routing), copied so this test has no cross-branch import. */
const UNIVERSAL = ["environment", "creatures", "weapons", "items", "magic", "vehicles", "gameplay", "quests", "minigames", "economy", "admin", "utility", "interface", "visuals", "audio", "performance"];
const GAME = GAME_BY_ID.zomboid;
const MODELS: ModelId[] = ["katara", "saka", "yakko"];
const PROMPTS = [
  "a frost lightning weapon",
  "horde night sirens every seventh night",
  "a doctor who trades antibiotics and heals you",
  "a poison fire summon thing",
  "teleport blink and fly with neon hud",
  "auto sort harvest with lunar moon power",
];
const cat = (key: CategoryKey) => CATEGORIES.find((c) => c.key === key)!;
const forge = (key: CategoryKey, prompt: string, model: ModelId, version = 1) =>
  buildModFiles({ game: GAME, category: cat(key), modName: prompt.split(" ").slice(1, 4).join(" ") || "Test Mod", prompt, model, version });

describe("zomboid GameSupport", () => {
  it("describes the game honestly and consistently", () => {
    assert.equal(support.id, "zomboid");
    assert.equal(support.language, "Lua");
    assert.equal(support.install.side, "both");
    assert.equal(support.install.packaging, "lua-folder");
    assert.ok(support.install.clientNote && support.install.clientNote.length > 40);
    assert.equal(support.verification.method, "static-lint");
    assert.equal(support.verification.canRunSandbox, false);
    assert.equal(support.versions.filter((v) => v.status === "current").length, 1);
    assert.equal(support.versions.find((v) => v.status === "current")!.version, PZ_TARGET.testedOn);
    assert.ok(support.versions.some((v) => v.version.startsWith("41") && v.status === "unsupported"));
    for (const c of support.categories) assert.ok(UNIVERSAL.includes(c), c);
    assert.ok(support.sources.length >= 10 && support.sources.every((s) => /^https:\/\//.test(s) && !s.includes("pzwiki.net")));
    assert.ok(support.unknowns.length >= 5);
  });

  it("every dangerous-API pattern and failure rule is a valid regex", () => {
    for (const d of support.dangerousApis) assert.doesNotThrow(() => new RegExp(d.pattern), d.pattern);
    assert.ok(support.knowledge && support.knowledge.version === PZ_TARGET.testedOn);
    for (const r of support.knowledge!.failureRules) assert.doesNotThrow(() => new RegExp(r.detect, "m"), r.id);
  });
});

describe("zomboid Lua structure lint", () => {
  it("accepts balanced Lua with loops, long strings and comments", () => {
    const ok = `--[[ header ]]\nlocal t = { a = "x]]", [[long\n]] }\nfor i = 1, 3 do\n  while false do end\n  if i then elseif x then else end\nend\nrepeat local y = 1 until true\nlocal f = function() return "end" end -- end`;
    assert.deepEqual(luaStructure(ok), []);
  });
  it("finds the usual generation mistakes", () => {
    assert.match(luaStructure("function a()\n if x then\nend").map((e) => e.message).join(), /never closed/);
    assert.match(luaStructure("local s = \"oops\nend").map((e) => e.message).join(), /unterminated string/);
    assert.match(luaStructure("f(1, {2)").map((e) => e.message).join(), /unmatched/);
    assert.match(luaStructure("end").map((e) => e.message).join(), /no open block/);
    assert.match(luaStructure("else").map((e) => e.message).join(), /outside an if/);
  });
  it("checks script block braces and trailing commas", () => {
    assert.deepEqual(scriptStructure("module A\n{\n  item B\n  {\n    Weight = 1,\n  }\n}"), []);
    assert.equal(scriptStructure("module A\n{\n  item B\n  {\n    Weight = 1\n  }\n").length, 2);
  });
});

describe("zomboid validator rejects broken or dangerous mods", () => {
  const base: ZomboidFile[] = [
    { path: "42/mod.info", content: "name=X\nid=X\nmodversion=1.0\nversionMin=42.15\n" },
    { path: "42/media/lua/client/X/Client.lua", content: "local a = 1\n" },
  ];
  const v = (extra: ZomboidFile[], files = base) => validateZomboidMod([...files, ...extra]);
  const rules = (r: ReturnType<typeof validateZomboidMod>) => r.issues.filter((i) => i.severity === "block").map((i) => i.rule);

  it("passes a minimal valid mod", () => assert.equal(v([]).ok, true));
  it("blocks the Build 41 layout and old translations", () => {
    const r = validateZomboidMod([{ path: "mod.info", content: "id=X\nname=X" }, { path: "media/lua/client/X.lua", content: "" }, { path: "42/media/lua/shared/Translate/EN/IG_UI_EN.txt", content: "IG_UI_EN = {}" }]);
    assert.ok(rules(r).includes("b41-layout"));
    assert.ok(rules(r).includes("mod.info"));
    assert.ok(rules(r).includes("txt-translations"));
  });
  it("blocks code runners, file access, reflection and obfuscation", () => {
    for (const bad of ['loadstring("x")()', 'local w = getFileWriter("../../x", true, false)', "getClassFieldVal(o, f)", 'os.execute("rm")', `local s = "${"\\104".repeat(20)}"`, "setfenv(1, {})"]) {
      const r = v([{ path: "42/media/lua/client/X/Bad.lua", content: bad }]);
      assert.equal(r.ok, false, bad);
      assert.ok(rules(r).includes("dangerous-api"), bad);
    }
  });
  it("ignores dangerous names that only appear in comments", () => assert.equal(v([{ path: "42/media/lua/client/X/C.lua", content: "-- never call loadstring( here\nlocal a = 1" }]).ok, true));
  it("blocks removed Build 42 APIs and old item syntax", () => {
    assert.equal(v([{ path: "42/media/lua/server/X/S.lua", content: "player:getStats():setFatigue(0)" }]).ok, false);
    const r = v([{ path: "42/media/scripts/x/items.txt", content: "module X\n{\n  item Y\n  {\n    Type = Weapon,\n    DisplayName = Y,\n  }\n}" }]);
    assert.ok(rules(r).includes("item-type-field"));
    assert.ok(rules(r).includes("display-name"));
    assert.ok(rules(v([{ path: "42/media/scripts/x/recipes.txt", content: "module X\n{\n  craftRecipe A\n  {\n    inputs\n    {\n      item 1 tags[Screwdriver] mode:keep,\n    }\n  }\n}" }])).includes("unnamespaced-tag"));
  });
  it("enforces the Build 42 multiplayer rules", () => {
    const action = "IST = ISBaseTimedAction:derive(\"IST\")\nfunction IST:perform() end";
    assert.ok(rules(v([{ path: "42/media/lua/client/X/A.lua", content: action }])).includes("mp-timed-action"));
    assert.ok(rules(v([{ path: "42/media/lua/shared/X/A.lua", content: action }])).includes("mp-timed-action")); // no getDuration/complete
    assert.ok(rules(v([{ path: "42/media/lua/client/X/C.lua", content: 'player:getInventory():AddItem("Base.Axe")' }])).includes("mp-items"));
  });
  it("blocks invalid translations and versionMin below 42.15", () => {
    assert.ok(rules(v([{ path: "common/media/lua/shared/Translate/EN/IG_UI.json", content: "{ nope" }])).includes("translation"));
    const old = validateZomboidMod([{ path: "42/mod.info", content: "name=X\nid=X\nversionMin=42.12\n" }, base[1]]);
    assert.ok(rules(old).includes("mod.info"));
  });
  it("parses mod.info, keeping repeated keys", () => assert.deepEqual(parseModInfo("poster=a.png\nposter=b.png\nid = X")["poster"], ["a.png", "b.png"]));
});

describe("zomboid generator output", () => {
  const keys = CATEGORIES.map((c) => c.key);

  it("every category x model x prompt passes the validator with no blocking issue", () => {
    let count = 0;
    for (const key of keys) for (const model of MODELS) for (const prompt of PROMPTS) {
      const files = forge(key, prompt, model, 1 + (count % 3));
      const report = validateZomboidMod(files.map((f) => ({ path: f.path, content: f.content })));
      const blocks = report.issues.filter((i) => i.severity === "block");
      assert.deepEqual(blocks, [], `${key}/${model}/"${prompt}": ${JSON.stringify(blocks.slice(0, 3))}`);
      count++;
    }
    assert.equal(count, keys.length * MODELS.length * PROMPTS.length);
  });

  it("Katara drafts stay within three files and still include mod.info", () => {
    for (const key of keys) {
      const files = forge(key, PROMPTS[0], "katara");
      assert.ok(files.length <= 3, key);
      assert.ok(files.some((f) => f.path === "42/mod.info"), key);
      assert.ok(files.some((f) => f.path.endsWith("/Main.lua")), key);
    }
  });

  it("writes a Build 42 manifest and JSON translations", () => {
    const files = forge("weapons", "an electric bat for zombies", "yakko");
    const info = parseModInfo(files.find((f) => f.path === "42/mod.info")!.content);
    assert.equal(info.versionMin[0], PZ_TARGET.versionMin);
    assert.match(info.id[0], /^[A-Za-z0-9_]+$/);
    assert.equal(info.modversion[0], "1.0");
    for (const t of ["Sandbox", "IG_UI", "ItemName", "Recipes", "Mod"]) {
      const f = files.find((x) => x.path === `common/media/lua/shared/Translate/EN/${t}.json`);
      assert.ok(f, t);
      assert.doesNotThrow(() => JSON.parse(f!.content), t);
    }
    const items = files.find((f) => f.path.endsWith("/items.txt"))!.content;
    assert.match(items, /ItemType = base:weapon,/);
    assert.match(items, /Categories = base:(axe|blunt),/);
    assert.doesNotMatch(items, /DisplayName|^\s*Type =/m);
    assert.match(files.find((f) => f.path.endsWith("/recipes.txt"))!.content, /tags\[base:screwdriver\]/);
    assert.ok(files.some((f) => f.path === "ASSETS.md"), "missing art is listed, not hidden");
  });

  it("keeps game-state changes on the server", () => {
    const files = forge("items", "a frost and fire device", "saka");
    const client = files.find((f) => f.path.includes("/lua/client/"))!.content;
    const actions = files.find((f) => f.path.endsWith("/Actions.lua"));
    assert.ok(actions && actions.path.includes("/lua/shared/"), "timed action is shared");
    assert.match(actions!.content, /:complete\(\)[\s\S]*UseAndSync\(\)/);
    assert.doesNotMatch(client, /setHealth|StartFire|AddItem|Effects\./);
    const server = files.find((f) => f.path.includes("/lua/server/"))!.content;
    assert.match(server, /^if isClient\(\) then return end$/m);
    const effects = files.find((f) => f.path.endsWith("/Effects.lua"))!.content;
    assert.match(effects, /canBurn/, "fire is guarded");
    assert.match(effects, /SafeHouse/);
  });

  it("routes weapon hits through a validated server command", () => {
    const files = forge("weapons", "a storm blade", "saka");
    const client = files.find((f) => f.path.includes("/lua/client/"))!.content;
    const server = files.find((f) => f.path.includes("/lua/server/"))!.content;
    assert.match(client, /Events\.OnHitZombie\.Add/);
    assert.match(client, /sendClientCommand\(player, MOD, command, args\)/);
    assert.match(server, /Events\.OnClientCommand\.Add/);
    assert.match(server, /DistanceTo\(player:getX\(\), player:getY\(\), args\.x, args\.y\) > 30/);
    assert.match(server, /getPrimaryHandItem\(\)/);
  });

  it("uses the Build 42 stats API and never the removed calls", () => {
    for (const key of keys) for (const prompt of PROMPTS) {
      const all = forge(key, prompt, "yakko").map((f) => f.content).join("\n");
      assert.doesNotMatch(all, /getStats\(\):(get|set)(Fatigue|Endurance|Panic|Stress)\(|setPoisonLevel|setRunSpeedModifier|getNumMoodles|:setL[xy]\(|:Is\(IsoFlagType/, `${key}: ${prompt}`);
    }
    assert.match(forge("creatures", "a frost thing", "yakko").map((f) => f.content).join("\n"), /CharacterStat\[name\]/);
  });

  it("is deterministic and version-aware", () => {
    const a = forge("mechanics", PROMPTS[1], "yakko", 2).map((f) => f.content).join();
    const b = forge("mechanics", PROMPTS[1], "yakko", 2).map((f) => f.content).join();
    assert.equal(a, b);
    assert.match(a, /modversion=2\.0/);
    assert.match(a, /Build 42 \(42\.15\+\)/);
  });

  it("the busted spec and sandbox options agree with Config defaults", () => {
    const built = zomboidLua({ game: GAME, category: cat("mechanics"), modName: "Horde Night Sirens", prompt: PROMPTS[1], model: "yakko", version: 1 });
    assert.match(built.config!.path, /^42\/media\/sandbox-options\.txt$/);
    assert.match(built.config!.content, /option HordeNightSirens\.Interval\n\{[\s\S]*default = 7,/);
    assert.deepEqual(luaStructure(built.test.content), []);
    assert.equal(JSON.parse(built.l10n!.content)["Sandbox_HordeNightSirens_Interval"], "Nights between events");
  });
});

