    assert.match(items, /Categories = base:(axe|blunt),/);
    assert.doesNotMatch(items, /DisplayName|^\s*Type =/m);
    assert.match(files.find((f) => f.path.endsWith("/recipes.txt"))!.content, /tags\[base:screwdriver\]/);
    assert.ok(files.some((f) => f.path === "ASSETS.md"), "missing art is listed, not hidden");
  });

  it("keeps game-state changes on the server", () => {
    const files = forge("items", "a frost and fire device", "saka");
    const client = files.find((f) => f.path.includes("/lua/client/"))!.content;
    const actions = files.find((f) => f.path.endsWith("/Actions.lua"));
    assert.ok(actions && actions.path.includes("/lua/shared/"), "timed action is shared");
    assert.match(actions!.content, /:complete\(\)[\s\S]*UseAndSync\(\)/);
    assert.doesNotMatch(client, /setHealth|StartFire|AddItem|Effects\./);
    const server = files.find((f) => f.path.includes("/lua/server/"))!.content;
    assert.match(server, /^if isClient\(\) then return end$/m);
    const effects = files.find((f) => f.path.endsWith("/Effects.lua"))!.content;
    assert.match(effects, /canBurn/, "fire is guarded");
    assert.match(effects, /SafeHouse/);
  });

  it("routes weapon hits through a validated server command", () => {
    const files = forge("weapons", "a storm blade", "saka");
    const client = files.find((f) => f.path.includes("/lua/client/"))!.content;
    const server = files.find((f) => f.path.includes("/lua/server/"))!.content;
    assert.match(client, /Events\.OnHitZombie\.Add/);
    assert.match(client, /sendClientCommand\(player, MOD, command, args\)/);
    assert.match(server, /Events\.OnClientCommand\.Add/);
    assert.match(server, /DistanceTo\(player:getX\(\), player:getY\(\), args\.x, args\.y\) > 30/);
    assert.match(server, /getPrimaryHandItem\(\)/);
  });

  it("uses the Build 42 stats API and never the removed calls", () => {
    for (const key of keys) for (const prompt of PROMPTS) {
      const all = forge(key, prompt, "yakko").map((f) => f.content).join("\n");
      assert.doesNotMatch(all, /getStats\(\):(get|set)(Fatigue|Endurance|Panic|Stress)\(|setPoisonLevel|setRunSpeedModifier|getNumMoodles|:setL[xy]\(|:Is\(IsoFlagType/, `${key}: ${prompt}`);
    }
    assert.match(forge("creatures", "a frost thing", "yakko").map((f) => f.content).join("\n"), /CharacterStat\[name\]/);
  });

  it("is deterministic and version-aware", () => {
    const a = forge("mechanics", PROMPTS[1], "yakko", 2).map((f) => f.content).join();
    const b = forge("mechanics", PROMPTS[1], "yakko", 2).map((f) => f.content).join();
    assert.equal(a, b);
    assert.match(a, /modversion=2\.0/);
    assert.match(a, /Build 42 \(42\.15\+\)/);
  });

  it("the busted spec and sandbox options agree with Config defaults", () => {
    const built = zomboidLua({ game: GAME, category: cat("mechanics"), modName: "Horde Night Sirens", prompt: PROMPTS[1], model: "yakko", version: 1 });
    assert.match(built.config!.path, /^42\/media\/sandbox-options\.txt$/);
    assert.match(built.config!.content, /option HordeNightSirens\.Interval\n\{[\s\S]*default = 7,/);
    assert.deepEqual(luaStructure(built.test.content), []);
    assert.equal(JSON.parse(built.l10n!.content)["Sandbox_HordeNightSirens_Interval"], "Nights between events");
  });
});

