import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { buildModFiles } from "./lib/cyrus/engine/templates";
import { CATEGORIES, GAME_BY_ID } from "./lib/cyrus/data";
import { validateZomboidMod } from "./lib/cyrus/games/zomboid.validate";
const PROMPTS = ["a frost lightning weapon", "horde night sirens every seventh night", "a doctor who trades antibiotics and heals you", "a poison fire summon thing", "teleport blink and fly with neon hud", "auto sort harvest with lunar moon power"];
const seen = new Map<string, number>(); let warns = new Map<string, number>();
for (const c of CATEGORIES) for (const model of ["katara", "saka", "yakko"] as const) for (const prompt of PROMPTS) {
  const files = buildModFiles({ game: GAME_BY_ID.zomboid, category: c, modName: prompt.split(" ").slice(1, 4).join(" "), prompt, model, version: 2 });
  const r = validateZomboidMod(files);
  for (const i of r.issues) { const k = `${i.severity} ${i.rule} ${i.message.slice(0, 90)} @${i.file?.replace(/[A-Z][A-Za-z]+(?=\/)/g, "X")}`; (i.severity === "block" ? seen : warns).set(k, ((i.severity === "block" ? seen : warns).get(k) ?? 0) + 1); }
  if (model !== "katara" && prompt === PROMPTS[3]) for (const f of files) { const p = `.zomboid-out/${c.key}-${model}/${f.path}`; mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, f.content); }
  if (model === "katara" && prompt === PROMPTS[0]) for (const f of files) { const p = `.zomboid-out/${c.key}-katara/${f.path}`; mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, f.content); }
}
console.log("BLOCKS"); for (const [k, v] of seen) console.log(v, k);
console.log("WARNS"); for (const [k, v] of warns) console.log(v, k);
E
grep -q "^.zomboid" .gitignore 2>/dev/null; git check-ignore .zomboid-debug.ts; timeout 1200 /opt/nxeon/scripts/devhost run --lock -- sh -c 'rm -rf .zomboid-out; npx tsx .zomboid-debug.ts; tar czf /tmp/zout.tgz .zomboid-out' 2>&1 | tail -40

