p='lib/cyrus/engine/games/zomboid.ts'
s=open(p).read()
old='''  if (lite) {
    /* One shared file, split at runtime: shared parts first, then client-only and server-only blocks. */'''
new='''  if (lite && extraClient.length) {
    /* UI drafts: vanilla ISUI classes only exist once client Lua loads, so the draft is a client file (+ a server file). */
    const own = (r: string) => r.includes(`"${cls}/`);
    const clientLua = file(`${L}/client/${cls}/Client.lua`, code`
      ${banner("client (Katara draft)")}
      ${[...new Set(clientRequires.filter((r) => !own(r)))]}
      ${cfgBody}
      local MOD = Config.MOD_ID

      ${extraClient.map((f) => f.content.replace(/^--\\[\\[[\\s\\S]*?\\]\\]\\n/, ""))}

      ${clientSrc}`);
    const serverLua = file(`${L}/server/${cls}/Server.lua`, code`
      ${banner("server (Katara draft)")}
      if isClient() then return end

      ${cfgBody}
      local MOD = Config.MOD_ID
      ${useEffects ? GAP : ""}
      ${useEffects ? effectsBody : ""}

      ${serverSrc}`);
    files.push(clientLua, ...(hasServer ? [serverLua] : []), modInfo);
  } else if (lite) {
    /* One shared file, split at runtime: shared parts first, then client-only and server-only blocks. */'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
E
echo ok

